function validate([word1, word2]) {
  if (word1.length < 1 || word1.length > 1000000) return 'word1 has 1 to 10^6 letters.';
  if (word2.length < 1 || word2.length > 10000) return 'word2 has 1 to 10^4 letters.';
  if (!/^[a-z]+$/.test(word1) || !/^[a-z]+$/.test(word2)) return 'Both strings contain only lowercase English letters.';
  return null;
}

