function validSubstringCount(word1, word2) {
  const need = new Array(26).fill(0);
  for (const ch of word2) {
    need[ch.charCodeAt(0) - 97]++;
  }
  let missing = word2.length;
  let left = 0;
  let count = 0;
  for (let right = 0; right < word1.length; right++) {
    const added = word1.charCodeAt(right) - 97;
    if (need[added] > 0) {
      missing--;
    }
    need[added]--;
    while (missing === 0) {
      const removed = word1.charCodeAt(left) - 97;
      need[removed]++;
      if (need[removed] > 0) {
        missing++;
      }
      left++;
    }
    count += left;
  }
  return count;
}

