function validSubstringCount(word1, word2) {
  // Look at every substring, count its letters and compare them with word2's counts.
  const want = {};
  for (const c of word2) want[c] = (want[c] || 0) + 1;
  let total = 0;
  for (let i = 0; i < word1.length; i++) {
    const have = {};
    for (let j = i; j < word1.length; j++) {
      have[word1[j]] = (have[word1[j]] || 0) + 1;
      if (Object.keys(want).every(c => (have[c] || 0) >= want[c])) total++;
    }
  }
  return total;
}

