function generate(rand, size) {
  const large = size === 'large';
  const k = large ? [2, 3, 5, 26][Math.floor(rand() * 4)] : 1 + Math.floor(rand() * 3);
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(0, k);
  // Uneven letter frequencies make some letters scarce, so valid windows have to stretch to collect them.
  const weights = Array.from({ length: k }, () => 0.2 + rand());
  const sum = weights.reduce((a, b) => a + b, 0);
  const letter = () => {
    let r = rand() * sum;
    for (let i = 0; i < k; i++) {
      r -= weights[i];
      if (r < 0) return letters[i];
    }
    return letters[k - 1];
  };
  const length1 = large ? 10000 : 1 + Math.floor(rand() * 12);
  // Large inputs pick a short, medium or long word2, so valid windows are tiny, mid-sized or nearly all of word1.
  const length2 = large ? [1 + Math.floor(rand() * 20), 100 + Math.floor(rand() * 2900), 5000 + Math.floor(rand() * 4000)][Math.floor(rand() * 3)] : 1 + Math.floor(rand() * 4);
  let word1 = '';
  let word2 = '';
  for (let i = 0; i < length1; i++) word1 += letter();
  for (let i = 0; i < length2; i++) word2 += letter();
  return [word1, word2];
}
